const upsertCredential = `-- name: UpsertCredential :exec
INSERT INTO integration.platform_credentials (provider_id, label, secret_ciphertext, key_id, rotated_at)
VALUES ($1, $2, $3, $4, now())
ON CONFLICT (provider_id, label) DO UPDATE SET secret_ciphertext = EXCLUDED.secret_ciphertext, key_id = EXCLUDED.key_id, rotated_at = now()
`

type UpsertCredentialParams struct {
	ProviderID       uuid.UUID
	Label            string
	SecretCiphertext []byte
	KeyID            string
}

func (q *Queries) UpsertCredential(ctx context.Context, arg UpsertCredentialParams) error {
	_, err := q.db.Exec(ctx, upsertCredential,
		arg.ProviderID,
		arg.Label,
		arg.SecretCiphertext,
		arg.KeyID,
	)
	return err
}
